// Кейс: .qa/tests/children/CHD-004.md · план: .qa/e2e-app/specs/app.md (1.7)
// «צילום ילד לזיהוי» при кадре БЕЗ лица: подсказка «לא רואים פנים…» или «יש יותר מדי חושך…», «התמונה מוכנה» не появляется за 10 с.
// ПРЕДУСЛОВИЕ ПРОГОНА: телефон лежит/стоит так, что в кадре нет лиц (стена/потолок/стол). Лицо, палец, чёрный кадр — вручную.
// Фото НЕ сохраняется («שימוש בתמונה» не нажимается), выход перезапуском. Разрешение камеры тест не выдаёт.
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = 'צילום ילד לזיהוי без лица: «לא רואים פנים בתמונה»/«יש יותר מדי חושך», без «התמונה מוכנה» #3f4c7c1e @iphone @app @prod-safe';

const CHILD = process.env.BANCI_CHILD || 'QA בדיקה';
const NO_FACE = 'לא רואים פנים בתמונה';
const DARK = 'יש יותר מדי חושך';
const READY = 'התמונה מוכנה';
const WINDOW_MS = 10000; // окно наблюдения: в баге «התמונה מוכנה» появлялась через 4–6 с

export default async function (app) {
  // 1. «ילדים» → карточка ребёнка.
  await onHome(app);
  await openTab(app, 'ילדים');
  const child = await app.scrollTo(by.contains(CHILD), { what: `ребёнок «${CHILD}» в «ילדים»` });
  await child.click();
  await app.waitFor(by.contains('בדיקה תקופתית'), { timeout: 15000, what: 'карточка ребёнка' });

  // 2. «צילום תמונה» (кнопка или строка «תמונה» → пункт «צילום תמונה»).
  if (await app.exists(by.contains('צילום תמונה'))) await app.tap(by.contains('צילום תמונה'));
  else {
    await app.tap('(name == "תמונה" OR label == "תמונה" OR name BEGINSWITH "תמונה" OR label BEGINSWITH "תמונה")', { what: 'строка «תמונה» в карточке' });
    if (await app.waitFor(by.contains('צילום תמונה'), { timeout: 3000 }).then(() => true, () => false)) await app.tap(by.contains('צילום תמונה'));
  }
  const sys = await app.alert();
  assert(!sys, `ПРЕДУСЛОВИЕ: разрешение камеры уже выдано (системное окно: «${sys?.text}»)`);

  // 3. Экран съёмки: в течение окна наблюдения только подсказки, без «התמונה מוכנה».
  const hint = `(${by.contains(NO_FACE)}) OR (${by.contains(DARK)})`;
  await app.waitFor(hint, { timeout: 15000, what: `подсказка «${NO_FACE} — כוונו את הפנים למסגרת» или «${DARK} — …» (в кадре не должно быть лиц)` });
  const end = Date.now() + WINDOW_MS;
  while (Date.now() < end) {
    assert(!(await app.exists(by.contains(READY))), `без лица нет «${READY}» (лицо в кадре? — переложить телефон)`);
    await new Promise((r) => setTimeout(r, 500)); // интервал опроса
  }
  assert(await app.exists(hint), 'подсказка всё ещё на экране');
  assert(!(await app.exists(by.exact('שימוש בתמונה'))), 'кнопки «שימוש בתמונה» нет (нечего сохранять)');

  // 4. Выход без сохранения.
  await app.restart();
}
